"""Exercise actual documented packaged ShiftDrop batch commands on owned files."""
from pathlib import Path
import argparse,subprocess,json,hashlib,os
p=argparse.ArgumentParser();p.add_argument('--executable',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();exe=a.executable.resolve();root=a.output.resolve()
if root.exists():raise FileExistsError('Case output must be new')
root.mkdir(parents=True);out=root/'copies';out.mkdir();inputs=root/'input';inputs.mkdir();source=inputs/'note.srt'
source.write_text('1\n00:00:01,007 --> 00:00:02,999\nKeep the original.\n\n2\n00:00:05,120 --> 00:00:07,250\nReview the saved copy.\n')
collision=out/'note.vtt';collision.write_text('WEBVTT\n\n00:00:00.000 --> 00:00:00.500\nExisting copy\n');hashfile=lambda f:hashlib.sha256(f.read_bytes()).hexdigest();originalHash=hashfile(source);collisionHash=hashfile(collision);events=[]
def run(name,args,expected):
 r=subprocess.run([str(exe),*map(str,args)],capture_output=True,text=True,timeout=30);events.append({'name':name,'exit':r.returncode,'stdout':r.stdout,'stderr':r.stderr});assert r.returncode==expected,(name,r.returncode,r.stdout,r.stderr);return r
run('new',['--batch-new',root/'queue',out,'vtt',source],0);published=[x for x in out.iterdir()if x!=collision];assert len(published)==1;result=published[0];nativeBytes=result.read_bytes();assert hashfile(source)==originalHash and hashfile(collision)==collisionHash
status=json.loads(run('fresh status',['--batch-status',root/'queue'],0).stdout);assert status['jobs'][0]['state']=='complete_verified';(root/'before-status.json').write_text(json.dumps(status,indent=2)+'\n');(root/'converted.vtt').write_bytes(nativeBytes)
manifest=json.loads((root/'queue/manifest.json').read_text());job=manifest['jobs'][0];stage=next((root/'queue').glob('result-*/*'));assert os.path.samestat(stage.stat(),result.stat());oldInode=result.stat().st_ino
# The retained stage keeps the old inode alive. Same-byte replacement is a different file.
result.unlink();result.write_bytes(nativeBytes);assert result.stat().st_ino!=oldInode;assert hashfile(result)==hashfile(stage)
held=json.loads(run('same bytes replaced',['--batch-status',root/'queue'],1).stdout);assert held['jobs'][0]['state']=='output_changed';(root/'held-status.json').write_text(json.dumps(held,indent=2)+'\n');run('held resume',['--batch-resume',root/'queue',out],2);assert result.read_bytes()==nativeBytes and hashfile(collision)==collisionHash
run('explicit new conversion',['--batch-new',root/'new-queue',out,'vtt',source],0);newFiles=[x for x in out.iterdir()if x not in [collision,result]];assert len(newFiles)==1 and newFiles[0].read_bytes()==nativeBytes;fresh=json.loads(run('fresh new status',['--batch-status',root/'new-queue'],0).stdout);assert fresh['jobs'][0]['state']=='complete_verified';(root/'new-status.json').write_text(json.dumps(fresh,indent=2)+'\n')
bad=inputs/'reversed.srt';bad.write_text('1\n00:00:03,000 --> 00:00:01,000\nInvalid reversed cue\n');before={x.name:x.read_bytes()for x in out.iterdir()};run('invalid cue',['--convert',bad,'--to','vtt','--output',out],1);assert {x.name:x.read_bytes()for x in out.iterdir()}==before;assert hashfile(source)==originalHash and hashfile(collision)==collisionHash
receipt={'source':'Actual packaged source-preview CLI, fresh process per command','originalSHA256':originalHash,'collisionSHA256':collisionHash,'convertedSHA256':hashfile(root/'converted.vtt'),'outputName':result.name,'newOutputName':newFiles[0].name,'before':status,'sameByteReplacement':held,'newExplicitConversion':fresh,'sameBytesDifferentFileIdentity':True,'oldResumeRefused':True,'originalAndCollisionPreserved':True,'invalidReversedCuePreservedOutputs':True,'nativeGUI':'Not exercised; Mac locked. No drag/wheel/picker claim.'};(root/'receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');(root/'events.json').write_text(json.dumps(events,indent=2)+'\n');print(json.dumps(receipt,indent=2))
